const staticData = $getWorkflowStaticData('global');
if (!staticData.lastMessageTime) staticData.lastMessageTime = {};
const chatId = $json.chatId;
const ts = Date.now();
staticData.lastMessageTime[chatId] = ts;
return { json: { ...$json, _debounceTs: ts } };

const staticData = $getWorkflowStaticData('global');
const chatId = $json.chatId;
if (staticData.lastMessageTime[chatId] !== $json._debounceTs) {
  return null;
}
return { json: $json };

let text = $json.output || '';
if (/ВНУТРЕННИЙ\s+АУДИТ/i.test(text)) {
  const idx = text.indexOf('---');
  if (idx !== -1) {
    text = text.slice(idx + 3).trim();
  } else {
    const parts = text.split(/\n\s*\n/);
    text = parts.slice(1).join('\n\n').trim() || text;
  }
}
return { json: { ...$json, output: text } };
